function courseConfig(){return{boundary:state.boundary,guides:state.guides,routes:state.routes,areas:state.areas,axes:state.axes,defaultAxes:state.defaultAxes,axisTees:state.axisTees,par3:state.par3,holeViews:state.holeViews,startView:state.startView,desktopStartView:state.desktopStartView,flagPositions:state.flagPositions,visualSettings:state.visualSettings,objects3d:state.objects3d,vegetationSections:state.vegetationSections}}
