  const startView=!isTouchDevice()&&state.desktopStartView?state.desktopStartView:state.startView;if(state.view==='overview'&&!top&&startView){viewer.camera.setView({destination:C.Cartesian3.fromDegrees(startView.lon,startView.lat,startView.height),orientation:{heading:startView.heading,pitch:startView.pitch,roll:startView.roll||0}});viewer.scene.requestRender();$('time').textContent='0:00 / 0:24';return}
